{"contract_markdown":"## vb-k563f: Known IpcError variant predicate

Replace private `assert_typed_ipc_error` with public `is_known_ipc_error` predicate that returns true for the 14 documented IpcError variants and false for any future unknown variant (via wildcard match). This makes the type-check explicit rather than a no-op match statement. All callsites assert the boolean result; fuzz targets remain compile-only.

```rust
pub fn is_known_ipc_error(e: &IpcError) -> bool {
    matches!(e,
        IpcError::Full | IpcError::Disconnected
        | IpcError::PayloadTooLarge { .. } | IpcError::InvalidMagic { .. }
        | IpcError::UnsupportedVersion { .. } | IpcError::UnknownCommand(_)
        | IpcError::ReservedNonZero { .. } | IpcError::PayloadLengthMismatch { .. }
        | IpcError::HeaderEncodeFailed | IpcError::HeaderDecodeFailed
        | IpcError::PayloadLengthOutOfRange { .. } | IpcError::PayloadEncodeFailed
        | IpcError::PayloadDecodeFailed | IpcError::ResponseDecodeFailed)
}
```"},
"predicate_function":"pub fn is_known_ipc_error(e: &IpcError) -> bool {
    use IpcError::*;
    matches!(e,
        Full | Disconnected
        | PayloadTooLarge { .. } | InvalidMagic { .. }
        | UnsupportedVersion { .. } | UnknownCommand(_)
        | ReservedNonZero { .. } | PayloadLengthMismatch { .. }
        | HeaderEncodeFailed | HeaderDecodeFailed
        | PayloadLengthOutOfRange { .. } | PayloadEncodeFailed
        | PayloadDecodeFailed | ResponseDecodeFailed)
}",
"export_line":"pub use crate::is_known_ipc_error;",
"tests_module":"mod tests {
    use super::*;
    use crate::IpcError;

    #[test]
    fn all_current_variants_are_known() {
        assert!(is_known_ipc_error(&IpcError::Full));
        assert!(is_known_ipc_error(&IpcError::Disconnected));
        assert!(is_known_ipc_error(&IpcError::PayloadTooLarge { actual: 10, limit: 5 }));
        assert!(is_known_ipc_error(&IpcError::InvalidMagic { actual: 0 }));
        assert!(is_known_ipc_error(&IpcError::UnsupportedVersion { actual: 99 }));
        assert!(is_known_ipc_error(&IpcError::UnknownCommand(42)));
        assert!(is_known_ipc_error(&IpcError::ReservedNonZero { actual: 1 }));
        assert!(is_known_ipc_error(&IpcError::PayloadLengthMismatch { header: 10, actual: 5 }));
        assert!(is_known_ipc_error(&IpcError::HeaderEncodeFailed));
        assert!(is_known_ipc_error(&IpcError::HeaderDecodeFailed));
        assert!(is_known_ipc_error(&IpcError::PayloadLengthOutOfRange { actual: u32::MAX }));
        assert!(is_known_ipc_error(&IpcError::PayloadEncodeFailed));
        assert!(is_known_ipc_error(&IpcError::PayloadDecodeFailed));
        assert!(is_known_ipc_error(&IpcError::ResponseDecodeFailed));
    }

    #[test]
    fn invalid_magic_is_known() {
        let header = [0u8; vb_ipc::IPC_HEADER_LEN];
        let result = vb_ipc::frame::decode_frame_header(&header);
        match result {
            Err(IpcError::InvalidMagic { actual }) => {
                assert_eq!(actual, 0);
                assert!(is_known_ipc_error(&result.unwrap_err()));
            }
            _ => assert!(false, "expected InvalidMagic"),
        }
    }
}",
